const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程求根公式' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: 'x²' },
      { kind: 'text', payload: '−' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '+' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '= 0' },
      { kind: 'text', payload: 'x =' },
      { kind: 'text', payload: '−b' },
      { kind: 'text', payload: '±' },
      { kind: 'text', payload: '√(' },
      { kind: 'text', payload: 'b²' },
      { kind: 'text', payload: '−' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: 'a' },
      { kind: 'text', payload: 'c' },
      { kind: 'text', payload: ')' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: 'a' },
      { kind: 'text', payload: 'a = 1' },
      { kind: 'text', payload: 'b = −4' },
      { kind: 'text', payload: 'c = 4' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 0' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var sx = W / 900;
    var sy = H / 600;
    var S = Math.min(sx, sy);
    function X(v) { return v * sx; }
    function Y(v) { return v * sy; }
    function line(x1, y1, x2, y2) {
      return [['M', X(x1), Y(y1)], ['L', X(x2), Y(y2)]];
    }
    function poly(points) {
      var cmds = [];
      for (var i = 0; i < points.length; i++) {
        cmds.push([i === 0 ? 'M' : 'L', X(points[i][0]), Y(points[i][1])]);
      }
      return cmds;
    }
    function circle(cx, cy, r) {
      return visualSdk.circle(X(cx), Y(cy), r * S);
    }
    var dark = '#26354A';
    var red = '#C0392B';
    var blue = '#1F5FAF';
    var green = '#2E8B57';
    var purple = '#7D3C98';
    var lw = Math.max(1, 2 * S);
    var paths = [
      { id: 'underA', commands: line(235, 110, 255, 110) },
      { id: 'underB', commands: line(345, 110, 365, 110) },
      { id: 'underC', commands: line(435, 110, 455, 110) },
      { id: 'boxTop', commands: line(340, 135, 580, 135) },
      { id: 'boxBottom', commands: line(340, 195, 580, 195) },
      { id: 'boxLeft', commands: line(340, 135, 340, 195) },
      { id: 'boxRight', commands: line(580, 135, 580, 195) },
      { id: 'leaderA', commands: poly([[180, 320], [300, 320], [425, 250]]) },
      { id: 'leaderB', commands: line(180, 120, 265, 165) },
      { id: 'leaderC', commands: line(720, 120, 530, 165) },
      { id: 'leaderDelta', commands: poly([[450, 430], [620, 430], [620, 165], [580, 165]]) },
      { id: 'fracBar', commands: line(215, 205, 610, 205) },
      { id: 'radOverline', commands: line(370, 145, 555, 145) },
      { id: 'dotA', commands: circle(425, 250, 4.5) },
      { id: 'dotB', commands: circle(265, 165, 4.5) },
      { id: 'dotC', commands: circle(530, 165, 4.5) },
      { id: 'dotDelta', commands: circle(580, 165, 4.5) }
    ];
    function labelNode(i, x, y, h, v, color) {
      return { type: 'label', contentId: metrics[i].contentId, anchor: { x: X(x), y: Y(y) }, hAlign: h, vAlign: v, color: color };
    }
    var children = [
      { type: 'path', pathId: 'underA', fill: red, stroke: { width: lw } },
      { type: 'path', pathId: 'underB', fill: blue, stroke: { width: lw } },
      { type: 'path', pathId: 'underC', fill: green, stroke: { width: lw } },
      { type: 'path', pathId: 'boxTop', fill: purple, stroke: { width: lw, dash: [5, 4] } },
      { type: 'path', pathId: 'boxBottom', fill: purple, stroke: { width: lw, dash: [5, 4] } },
      { type: 'path', pathId: 'boxLeft', fill: purple, stroke: { width: lw, dash: [5, 4] } },
      { type: 'path', pathId: 'boxRight', fill: purple, stroke: { width: lw, dash: [5, 4] } },
      { type: 'path', pathId: 'leaderA', fill: red, stroke: { width: lw } },
      { type: 'path', pathId: 'leaderB', fill: blue, stroke: { width: lw } },
      { type: 'path', pathId: 'leaderC', fill: green, stroke: { width: lw } },
      { type: 'path', pathId: 'leaderDelta', fill: purple, stroke: { width: lw, dash: [5, 4] } },
      { type: 'path', pathId: 'fracBar', fill: dark, stroke: { width: lw } },
      { type: 'path', pathId: 'radOverline', fill: dark, stroke: { width: lw } },
      { type: 'path', pathId: 'dotA', fill: red },
      { type: 'path', pathId: 'dotB', fill: blue },
      { type: 'path', pathId: 'dotC', fill: green },
      { type: 'path', pathId: 'dotDelta', fill: purple },
      labelNode(0, 450, 45, 'center', 'middle', dark),
      labelNode(1, 245, 95, 'center', 'middle', red),
      labelNode(2, 285, 95, 'center', 'middle', dark),
      labelNode(3, 325, 95, 'center', 'middle', dark),
      labelNode(4, 355, 95, 'center', 'middle', blue),
      labelNode(5, 380, 95, 'center', 'middle', dark),
      labelNode(6, 415, 95, 'center', 'middle', dark),
      labelNode(7, 445, 95, 'center', 'middle', green),
      labelNode(8, 490, 95, 'center', 'middle', dark),
      labelNode(9, 195, 210, 'right', 'middle', dark),
      labelNode(10, 265, 165, 'center', 'middle', blue),
      labelNode(11, 310, 165, 'center', 'middle', dark),
      labelNode(12, 350, 165, 'center', 'middle', dark),
      labelNode(13, 405, 165, 'center', 'middle', blue),
      labelNode(14, 445, 165, 'center', 'middle', dark),
      labelNode(15, 480, 165, 'center', 'middle', dark),
      labelNode(16, 505, 165, 'center', 'middle', red),
      labelNode(17, 530, 165, 'center', 'middle', green),
      labelNode(18, 560, 165, 'center', 'middle', dark),
      labelNode(19, 400, 250, 'center', 'middle', dark),
      labelNode(20, 425, 250, 'center', 'middle', red),
      labelNode(21, 135, 320, 'center', 'middle', red),
      labelNode(22, 135, 120, 'center', 'middle', blue),
      labelNode(23, 765, 120, 'center', 'middle', green),
      labelNode(24, 450, 460, 'center', 'middle', purple)
    ];
    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
